package com.nigson.acceptance.carrier;
import java.time.*;
import java.net.*;
import java.net.http.*;
import java.util.*;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.acceptance.provider.JobHttpAcceptance;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;
/** Actual BFF encrypted sessions/current staff, KMS SDK delegation and scoped private JWT HTTP. */
public final class CarrierReconciliationHttpAcceptance {
 private CarrierReconciliationHttpAcceptance(){}
 public static void configure(Map<String,Object> properties){if(System.getenv("NIGSON_TEST_CARRIER")!=null)properties.put("NIGSON_CARRIER_RECONCILIATION_ENABLED","true");}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,JobHttpAcceptance.Fixture upstream)throws Exception{
  if(System.getenv("NIGSON_TEST_CARRIER")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var createdSessions=new ArrayList<String>();try(var f=new ShipmentFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){CarrierContextPersistenceTest.freeze(f);var shipment=f.create("5","FEDEX",null,"reconciliation-http-intent");CarrierReconciliationPersistenceTest.ngMarket(f);f.inventory.jdbc.update("UPDATE commerce.party SET identity_issuer=? WHERE id=?",upstream.issuer,f.inventory.actor.party());var cookies=new ArrayList<String>();var csrf=new ArrayList<String>();for(int i=0;i<2;i++){var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String token=JdbcSessionTrust.opaque();csrf.add(token);String id=sessions.authenticate(flow.sessionId(),new SessionRecord(1,f.inventory.actor.party(),upstream.issuer,f.inventory.actor.party().toString(),Instant.now(),Instant.now().minusSeconds(i==0?0:901),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),token,SessionRecord.TokenState.READY));createdSessions.add(id);cookies.add("__Host-nigson-session="+id);}String uri=base+"/api/v1/staff/shipments/"+shipment.id()+"/booking-reconciliation",body="{\"reason\":\"Synthetic operator reference reconciliation\"}";int before=upstream.reconciliationEffects.get(),signs=upstream.signs.get();
   assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body))).statusCode()).isEqualTo(401);assertThat(send(http,command(uri,cookies.getFirst(),"wrong",body,"csrf",0)).statusCode()).isEqualTo(401);assertThat(send(http,command(uri,cookies.get(1),csrf.get(1),body,"stale-mfa",0)).statusCode()).isEqualTo(403);assertThat(send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body,"version",2)).statusCode()).isEqualTo(412);assertThat(send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body.replace("}",",\"mode\":\"LIVE\"}"),"injected",0)).statusCode()).isEqualTo(400);assertThat(upstream.reconciliationEffects.get()).isEqualTo(before);assertThat(upstream.signs.get()).isEqualTo(signs);
   String key=UUID.randomUUID().toString();upstream.duringReconciliation=()->{var manager=app.getBean(org.springframework.transaction.PlatformTransactionManager.class);new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{f.inventory.jdbc.execute("SET LOCAL lock_timeout='500ms'");f.inventory.jdbc.queryForMap("SELECT id FROM commerce.shipment WHERE id=? FOR UPDATE",shipment.id());assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE resource_id=? AND operation='API-191-PRIVATE-ACK' AND state='RUNNING' AND response_body->>'outcome'='CALLING'",Integer.class,shipment.id())).isEqualTo(1);});};upstream.reconciliationAfterAccept=true;var unknown=send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body,key,0));assertThat(unknown.statusCode()).as("uncertain source command: %s",unknown.body()).isEqualTo(503);assertThat(unknown.body()).doesNotContain("bookingRequestId","protected remote");assertThat(upstream.reconciliationEffects.get()).isEqualTo(before+1);f.inventory.jdbc.update("UPDATE commerce.shipment SET version=version+1,status='EXCEPTION' WHERE id=?",shipment.id());var accepted=send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body,key,0));assertThat(accepted.statusCode()).as("recovered source command: %s",accepted.body()).isEqualTo(202);var dto=EventCodec.JSON.readTree(accepted.body());assertThat(dto.propertyNames()).containsExactlyInAnyOrder("shipmentId","state","jobId");assertThat(dto.path("jobId").asString()).isEqualTo(upstream.reconciliationJob.toString());assertThat(accepted.headers().firstValue("Cache-Control")).contains("no-store");assertThat(upstream.reconciliationEffects.get()).isEqualTo(before+1);int completedSigns=upstream.signs.get(),requests=upstream.reconciliationRequests.get();assertThat(send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body,key,0)).body()).isEqualTo(accepted.body());assertThat(upstream.signs.get()).isEqualTo(completedSigns);assertThat(upstream.reconciliationRequests.get()).isEqualTo(requests);assertThat(send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body.replace("reference","changed reference"),key,0)).statusCode()).isEqualTo(409);assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(f.inventory.jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");f.inventory.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",f.inventory.actor.party());assertThat(send(http,command(uri,cookies.getFirst(),csrf.getFirst(),body,key,0)).statusCode()).isEqualTo(403);assertThat(upstream.reconciliationRequests.get()).isEqualTo(requests);
  }finally{upstream.duringReconciliation=()->{};for(var id:createdSessions)sessions.logout(id);}
 }
 private static HttpRequest.Builder command(String uri,String cookie,String csrf,String body,String key,long version){return HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("If-Match","\""+version+"\"").header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
